  image "img_light-regent-xouhoulong-beacon-lit-chang-rampart_1772879826161", role: :inline, url: "https://theiceremembers.com/raw/project_1765083188592/img_light-regent-xouhoulong-beacon-lit-chang-rampart_1772879826161", anchor: "The aurora painted Xouhoulong's plaza in bands of violet and ice-blue", anchor_index: 0, caption: "The Accord's architect at the height of his power, before the cracks.", size: :large, reference_id: "imgref_1772835735959_0"
  image "img_light-regent-xouhoulong-beacon-lit-chang-rampart_1772879872567", role: :inline, url: "https://theiceremembers.com/raw/project_1765083188592/img_light-regent-xouhoulong-beacon-lit-chang-rampart_1772879872567", anchor: "something in the deep answered—not words, not sound, but pressure", anchor_index: 9304, caption: "The moment the ice began to remember what it had been hiding.", size: :large, reference_id: "imgref_1772835735959_1"
  image "img_light-regent-xouhoulong-beacon-lit-chang-rampart_1772879868520", role: :inline, url: "https://theiceremembers.com/raw/project_1765083188592/img_light-regent-xouhoulong-beacon-lit-chang-rampart_1772879868520", anchor: "The Mirror is cracked, sir", anchor_index: 15202, caption: "The seal that blessed seven cycles of secret work, now broken.", size: :medium, reference_id: "imgref_1772835735959_2"
  image "img_light-regent-xouhoulong-beacon-lit-chang-rampart_1772879919473", role: :inline, url: "https://theiceremembers.com/raw/project_1765083188592/img_light-regent-xouhoulong-beacon-lit-chang-rampart_1772879919473", anchor: "he walked toward the sealed southern gallery where the aurora would not go", anchor_index: 21465, caption: "The moment belief left him, and the plaza became a monument to what it had destroyed.", size: :large, reference_id: "imgref_1772835735959_3"
end
